#!/bin/bash
sed -i 's/fun ChartBox/fun CategoryDistributionSection(todos: List<TodoItem>, categories: List<Category>) {\n    val categoryStats = remember(todos, categories) {\n        val stats = categories.map { cat ->\n            val total = todos.count { it.categoryId == cat.id }\n            val completed = todos.count { it.categoryId == cat.id \&\& it.isCompleted }\n            val progress = if (total > 0) completed.toFloat() \/ total else 0f\n            Triple(cat.name, safeParseColor(cat.colorHex, NeonCyan), Pair("$completed\/$total", progress))\n        }\n        val uncategorizedTotal = todos.count { it.categoryId == null }\n        val uncategorizedCompleted = todos.count { it.categoryId == null \&\& it.isCompleted }\n        if (uncategorizedTotal > 0) {\n            stats + Triple("Uncategorized", TextSecondary, Pair("$uncategorizedCompleted\/$uncategorizedTotal", uncategorizedCompleted.toFloat() \/ uncategorizedTotal))\n        } else stats\n    }\n    Column(modifier = Modifier.fillMaxWidth()) {\n        Text("Category Distribution", color = TextPrimary, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, modifier = Modifier.padding(bottom = 16.dp, start = 4.dp))\n        Box(modifier = Modifier.fillMaxWidth().background(SlateDark, RoundedCornerShape(24.dp)).border(1.dp, BorderColor, RoundedCornerShape(24.dp)).padding(20.dp)) {\n            Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {\n                categoryStats.forEach { (name, color, pair) ->\n                    CategoryDistributionItem(name, color, pair.first, pair.second)\n                }\n            }\n        }\n    }\n}\n\n@Composable\nfun ChartBox/g' app/src/main/java/com/example/ui/ProgressScreen.kt
